WITH gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, reading_ts, temp_c, humidity, pressure, status_bits, firmware, session_start_flag, island_id FROM islands ORDER BY pressure DESC NULLS FIRST
